int main() {
    int rolls = 0;
    rolls = b2c::ask<int>("How many times should I roll the die? ");
    std::cout << "" << '\n';
    if (rolls < 1) {
        std::cout << "Roll at least once." << '\n';
        return 1;
    }
    std::map<int, int> counts{};
    for (int face = 1; face <= 6; ++face) {
        counts[face] = 0;
    }
    for (int i = 0; i < rolls; ++i) {
        int face = b2c::random_int(1, 6);
        counts[face] = counts.at(face) + 1;
    }
    std::cout << std::fixed << std::setprecision(1);
    int total = 0;
    int most_common = 1;
    for (const auto& [face, count] : counts) {
        std::cout << face << ": " << count << " (" << count * 100.0 / rolls << "%)" << '\n';
        total += count;
        if (count > counts.at(most_common)) {
            most_common = face;
        }
    }
    std::cout << "Faces: " << static_cast<int>(counts.size()) << '\n';
    std::cout << "Total: " << total << '\n';
    std::cout << "Most common face: " << most_common << '\n';
    return 0;
}
